    #cafeTable th[aria-sort] .sort-btn { padding: 8px 5px; white-space: normal; font-size: 11.5px; line-height: 1.2; }
    #cafeTable th[aria-sort]:first-child .sort-btn { padding-left: 0; }
    #cafeTable th[aria-sort]:last-child .sort-btn { padding-right: 0; }
