    .orders-table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
    .orders-table tbody tr {
      display: grid; grid-template-columns: 1fr auto; gap: 4px 12px;
      grid-template-areas: "id total" "cust status" "chan items";
      padding: 12px 0; border-bottom: 1px solid var(--grid);
    }
    .orders-table tbody tr:last-child { border-bottom: 0; }
    .orders-table tbody tr.empty-row { display: table-row; }
    .orders-table tbody th, .orders-table tbody td { padding: 0; border: 0; background: none !important; }
    .orders-table .c-id { grid-area: id; }
    .orders-table .c-cust { grid-area: cust; }
    .orders-table .c-chan { grid-area: chan; }
    .orders-table .c-items { grid-area: items; color: var(--ink-2); font-size: 12.5px; }
    .orders-table .c-total { grid-area: total; font-weight: 650; }
    .orders-table .c-status { grid-area: status; text-align: right; }
    .m-only { display: inline; }
  }""")
rep('<table>\n              <caption class="sr-only">Recent orders</caption>', '<table class="orders-table">\n              <caption class="sr-only">Recent orders</caption>')
rep('''      const idCell = el("th", { scope: "row" });''', '''      const idCell = el("th", { scope: "row", class: "c-id" });''')
rep('''      const chCell = el("td");''', '''      const chCell = el("td", { class: "c-chan" });''')
rep('''      const stCell = el("td");''', '''      const stCell = el("td", { class: "c-status" });''')
rep('''      tr.append(idCell, el("td", null, o.customer), chCell,
        el("td", { class: "num" }, String(o.items)), el("td", { class: "num" }, fmtUSD2(o.total)), stCell);''',
